import{_ as t,l as o,o as a,c as l,v as r,p as s,x as i,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"羊群与信息级联","description":"","frontmatter":{"title":"羊群与信息级联","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/herding-cascades.md","filePath":"econ/herding-cascades.md","lastUpdated":1789023840000}'),E={name:"econ/herding-cascades.md"};function p(A,e,B,m,_,f){const n=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="羊群与信息级联" tabindex="-1">羊群与信息级联 <a class="header-anchor" href="#羊群与信息级联" aria-label="Permalink to &quot;羊群与信息级联&quot;">​</a></h1><div class="epigraph"><p>一旦前面几个人的行动已经把后验锁死，后面的人理性地扔掉自己的信号——社会学习停止，错误可以永久化。</p><footer>—— Banerjee, A Simple Model of Herd Behavior, QJE 1992；Bikhchandani, Hirshleifer and Welch, JPE 1992</footer></div><p><a href="/econ/abreu-brunnermeier">上一课</a>是知情者等同步。本课缺口是不知情者向行动学习：序列选择里，公共后验可以压过私有信号，级联开始。不重写攻击阈值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Banerjee（1992）与 Bikhchandani、Hirshleifer、Welch（1992，BHW）：决策者按顺序行动，看到前人选择，收到独立私有信号。最优是贝叶斯更新后选期望更好的项。若前两人已经同向，第三人的信号往往不够翻转公共后验，他模仿——级联。此后行动不再泄露信号，信息加总失败。缺口是给羊群一个<strong>信息外部性</strong>定义，区别于 DSSW 情绪或社会偏好里的模仿。</p><p>Scharfstein 与 Stein（1990）的声誉羊群：经理为了不显得比同行笨而模仿，即使有私有信息。那是代理，与 BHW 的纯信息级联并列。</p><p><span class="marginnote">级联对信号质量极敏感：一点点公共信息或打乱顺序就能打破。脆弱是可检验含义，不是缺陷。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两状态、二元信号、序列行动。计算公共似然，标出级联开始的历史。对照：若能看到前人的信号而非行动，级联不会发生。金融：IPO 认购、分析师推荐、存款挤兑的信息版本（与 Diamond–Dybvig 的流动性版本分工，不重写银行课）。</p>',9)),(a(),s(c,null,{default:i(()=>[h(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E7%A7%81%E6%9C%89%E4%BF%A1%E5%8F%B7%20%2B%20%E8%A7%82%E5%AF%9F%E5%89%8D%E4%BA%BA%E8%A1%8C%E5%8A%A8%22%5D%20--%3E%20BAY%5B%22%E8%B4%9D%E5%8F%B6%E6%96%AF%E5%85%AC%E5%85%B1%E5%90%8E%E9%AA%8C%22%5D%0A%20%20BAY%20--%3E%20CAS%5B%22%E5%90%8E%E9%AA%8C%E9%94%81%E6%AD%BB%3A%20%E6%89%94%E6%8E%89%E8%87%AA%E5%B7%B1%E7%9A%84%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CAS%20--%3E%20STOP%5B%22%E7%A4%BE%E4%BC%9A%E5%AD%A6%E4%B9%A0%E5%81%9C%E6%AD%A2%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是行动对信号的压缩。行动是粗信号，一旦公共信念越过阈值，后人的行动与自己的信号无关，后人的观察者学不到新东西。价格若即时充分反映所有私有信号，级联难以形成——因此级联模型通常假定离散选择或对价格反应迟钝，与 <a href="/econ/emh">EMH</a> 半强式紧张。Hong–Stein 的扩散是空间上的分段；级联是时间上的停止学习。两者都是信息加总失败。</p><p>与 AB：AB 的玩家已经知道泡沫，等资本；级联的玩家还在猜状态，模仿前人。</p><p>行动是对信号的粗压缩：买/不买两个字母，装不下连续后验。公共信念一旦越过阈值，后人的最优是模仿，其行动不再含私有信息，学习停止。若能看到前人信号本身，级联不会发生。价格若连续且充分揭示，级联空间缩小——故模型常配离散选择。Scharfstein–Stein 的声誉羊群是代理：怕显得与众不同，即使没有信息外部性。本课以 BHW 纯信息为主。不写订单流。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>连续价格、内生顺序、逆向选择会改变级联区域。现场「跟风」混杂声誉、补偿基准与真正的信息外部性。本课不把基金抱团全部写成 BHW。也不写订单流毒化——微观结构课。</p><p>后课默认：有限注意力是另一种信息加总失败：不是扔掉信号，是根本没看见公告。</p><p>行动是粗信号；公共后验锁死后人扔掉私有信号，社会学习停止。级联脆弱，一点点公共信息就能打破。</p><p>AB 是知情者等动手；级联是猜状态的人模仿前人。HS 是空间扩散，这里是时间上停止学习。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信息级联：理性模仿使私有信号停止进入公共信念。</li><li>与情绪羊群、声誉羊群分工；脆弱性是含义。</li><li>对照 AB（知情等待）与 HS（分段扩散）。</li><li>若能看见前人信号本身，级联不会发生。</li><li>声誉羊群是代理，与纯信息外部性并列。</li><li>出处：Banerjee, <em>QJE</em> 1992；Bikhchandani, Hirshleifer and Welch, <em>JPE</em> 1992。</li></ul>',11))])}const b=t(E,[["render",p]]);export{S as __pageData,b as default};
